(x, y, t) => {
  const cx = 240, cy = 120;
  const wx1 = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const wy1 = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const wx2 = Math.sin(x*0.005+t*0.1)*25 + Math.cos(y*0.008-t*0.15)*20;
  const wy2 = Math.cos(y*0.006-t*0.12)*20 + Math.sin(x*0.007+t*0.08)*25;
  const sx = x + wx1 + wx2*0.5, sy = y + wy1 + wy2*0.5;
  const src = [];
  for (let i = 0; i < 9; i++) {
    const ph = i*0.698, oR = 60+i*18, oS = 0.2+i*0.05;
    src.push([
      240+Math.cos(t*oS+ph)*oR+Math.sin(t*0.15+i)*30,
      120+Math.sin(t*oS*0.8+ph)*oR*0.6+Math.cos(t*0.2+i*2)*20,
      0.04+(i%3)*0.025, 1.2+i*0.2, 1.0-i*0.08
    ]);
  }
  let aS=0, iS=0, wS=0, tA=0;
  for (const [sX,sY,f,sp,amp] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp)*amp;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*amp;
    wS += Math.sin(d*f*1.3-t*sp*0.4+2.8)*amp*0.5;
    tA += amp;
  }
  const act=aS/tA, inh=iS/tA, wav=wS/tA;
  const bg1 = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2 = Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3 = Math.sin(sx*0.08+sy*0.06-t*0.5)*Math.sin(sx*0.05-sy*0.09+t*0.7)*0.15;
  const bg = bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.35;
  const sp2=(Math.sin(dist*0.08+ang*2-t*0.8)+Math.sin(dist*0.03-ang*5+t))*0.2;
  const spiral=sp1+sp2;
  const micro=(Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.5)+Math.sin((sx*0.2+sy*0.15)+t*1.5)*Math.sin((-sx*0.15+sy*0.2)-t*1.8))*0.12;
  const feed=act+bg*0.3+spiral+wav*0.4+micro;
  const kill=inh*0.7+Math.sin(dist*0.03-t*0.5)*0.15;
  const reaction=Math.tanh((feed-kill)*2.5);
  let mD1=999, mD2=999;
  const cp=t*0.3;
  for (let i=0;i<7;i++){
    const cx2=(Math.sin(i*1.7+cp)*0.5+0.5)*480, cy2=(Math.cos(i*2.3+cp*0.7)*0.5+0.5)*240;
    const d=Math.sqrt((sx-cx2)**2+(sy-cy2)**2);
    if(d<mD1){mD2=mD1;mD1=d}else if(d<mD2){mD2=d}
  }
  const cellEdge=Math.max(0,1-(mD2-mD1)*0.15)*0.25;
  const blend=reaction*0.65+cellEdge*0.15+micro*0.1+spiral*0.1;
  const v=Math.tanh(blend*1.8)*0.5+0.5;
  const pal=[[5,10,45],[12,45,90],[18,95,120],[25,150,135],[60,180,110],[160,190,70],[220,180,50],[220,140,55],[200,95,60],[170,55,70],[120,35,80],[70,25,75],[30,15,60],[5,10,45]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const eS=Math.abs(reaction), glow=eS>0.6?1.0+(eS-0.6)*0.5:1.0;
  const sh=Math.sin(t*0.15)*0.05;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f+sh*20)*lum*glow))|0,
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*glow))|0,
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f-sh*15)*lum*glow))|0
  ];
}
